import { createHmac } from "node:crypto";
import { z } from "zod";
import { createSessionToken, readSessionToken, SESSION_MAX_AGE_SECONDS } from "./session-token";

const timestamp = z.number().int().nonnegative().safe();
const opaqueId = z.string().regex(/^[A-Za-z0-9_-]{22,128}$/u);
const principalId = z.string().regex(/^[A-Za-z0-9_-]{1,128}$/u);
const epoch = z.number().int().nonnegative().safe();
const maximumMs = SESSION_MAX_AGE_SECONDS * 1_000;

/** Disconnected server-row contract; id must be generated by a CSPRNG (>=128 bits). */
export const sessionInstanceSchema = z
  .object({
    id: opaqueId,
    principalId,
    authzEpochAtIssue: epoch,
    issuedAtMs: timestamp,
    expiresAtMs: timestamp,
    revokedAtMs: timestamp.nullable(),
  })
  .strict()
  .refine(
    (row) =>
      row.id !== row.principalId &&
      row.expiresAtMs > row.issuedAtMs &&
      row.expiresAtMs - row.issuedAtMs <= maximumMs,
  );
export type SessionInstance = z.infer<typeof sessionInstanceSchema>;

const currentPrincipalSchema = z
  .object({
    id: principalId,
    authzEpoch: epoch,
    disabled: z.boolean(),
  })
  .strict();

/** Version/domain separation, reusing the existing HMAC/lifetime implementation. */
function v2Secret(secret: string): string {
  if (typeof secret !== "string" || secret.length === 0)
    throw new TypeError("Session secret required.");
  return createHmac("sha256", secret).update("oratlas/session-instance/v2").digest("hex");
}

/** Signing does not insert a row or confer authority. No production caller exists. */
export function createSessionInstanceToken(instance: SessionInstance, secret: string): string {
  const row = sessionInstanceSchema.parse(instance);
  return `v2.${createSessionToken(row.id, v2Secret(secret), row.issuedAtMs)}`;
}

export interface ValidSessionInstance {
  readonly principalId: string;
  readonly sessionBinding: string;
  readonly validUntilMs: number;
}

/**
 * Validate caller-supplied server snapshots only; this is NOT a fresh DB read or
 * a revocation fence. A future adapter must retrieve both rows from authority
 * and order the actual effect using the separately reviewed S1 coordinator.
 */
export function validateSessionInstanceToken(
  token: unknown,
  instance: unknown,
  currentPrincipal: unknown,
  secret: string,
  nowMs: number,
): ValidSessionInstance | null {
  try {
    if (
      !timestamp.safeParse(nowMs).success ||
      typeof token !== "string" ||
      !token.startsWith("v2.")
    )
      return null;
    const parsedRow = sessionInstanceSchema.safeParse(instance);
    const principal = currentPrincipalSchema.safeParse(currentPrincipal);
    if (!parsedRow.success || !principal.success) return null;
    const row = parsedRow.data;
    const inner = token.slice(3);
    const id = readSessionToken(inner, v2Secret(secret), nowMs);
    // Binding the full deterministic token also checks the row's issue time;
    // a second signed token for this id cannot silently select another row age.
    if (
      !id ||
      id !== row.id ||
      token !== createSessionInstanceToken(row, secret) ||
      row.principalId !== principal.data.id ||
      row.authzEpochAtIssue !== principal.data.authzEpoch ||
      principal.data.disabled ||
      row.revokedAtMs !== null ||
      nowMs < row.issuedAtMs ||
      nowMs >= row.expiresAtMs
    )
      return null;
    return Object.freeze({
      principalId: row.principalId,
      sessionBinding: row.id,
      validUntilMs: row.expiresAtMs,
    });
  } catch {
    return null;
  }
}
